import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useTier } from '../config/TierContext';
import { Tier } from '../config/tiers';

export const SIDEBAR_WIDTH = 268;

const BST_BLUE = '#1D3FA8';
const BST_BLUE_DARK = '#152d7a';
const TIERS: Tier[] = ['Starter', 'Essentials', 'Pro'];

const navItems: { path: string; label: string; icon: React.ReactNode; section?: string }[] = [
  {
    path: '/dashboard',
    label: 'Overview',
    section: 'Dashboard',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <path d="M3 10.5L12 3l9 7.5" strokeLinecap="round" strokeLinejoin="round" />
        <path d="M5 10v10h14V10" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
  {
    path: '/performance',
    label: 'Performance & Ranking',
    section: 'Analytics',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <path d="M18 20V10M12 20V4M6 20v-6" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
  {
    path: '/time-development',
    label: 'Time Development',
    section: 'Analytics',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <circle cx="12" cy="12" r="9" />
        <path d="M12 7v5l3 3" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
  {
    path: '/quality',
    label: 'Quality & Failures',
    section: 'Analytics',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" strokeLinecap="round" strokeLinejoin="round" />
        <line x1="12" y1="9" x2="12" y2="13" strokeLinecap="round" />
        <line x1="12" y1="17" x2="12.01" y2="17" strokeLinecap="round" />
      </svg>
    ),
  },
  {
    path: '/geography',
    label: 'Geography & Customers',
    section: 'Analytics',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z" strokeLinecap="round" strokeLinejoin="round" />
        <circle cx="12" cy="9" r="2.5" />
      </svg>
    ),
  },
  {
    path: '/search',
    label: 'Delivery Notes',
    section: 'Tools',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" strokeLinecap="round" strokeLinejoin="round" />
        <path d="M14 2v6h6M16 13H8M16 17H8M10 9H8" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
  {
    path: '/pricing',
    label: 'Revenue & Billing',
    section: 'Tools',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <rect x="2" y="5" width="20" height="14" rx="2" />
        <path d="M2 10h20" strokeLinecap="round" />
        <path d="M6 15h4M14 15h4" strokeLinecap="round" />
      </svg>
    ),
  },
  {
    path: '/knowledge-hub',
    label: 'Knowledge Hub',
    section: 'Tools',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <path d="M4 19V5a2 2 0 0 1 2-2h4v16H6a2 2 0 0 0-2 2zm16 0V5a2 2 0 0 0-2-2h-4v16h4a2 2 0 0 1 2 2z" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
];

export default function Sidebar() {
  const location = useLocation();
  const { tier, setTier, spotterEnabled } = useTier();

  const linkStyle = (path: string): React.CSSProperties => {
    const active = location.pathname === path;
    return {
      display: 'flex',
      alignItems: 'center',
      gap: 12,
      textDecoration: 'none',
      fontSize: 13.5,
      fontWeight: active ? 600 : 400,
      color: active ? '#ffffff' : 'rgba(255,255,255,0.72)',
      padding: '10px 12px',
      borderRadius: 8,
      backgroundColor: active ? 'rgba(255,255,255,0.18)' : 'transparent',
      transition: 'all 0.15s ease',
      marginBottom: 2,
    };
  };

  return (
    <aside
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        bottom: 0,
        width: SIDEBAR_WIDTH,
        backgroundColor: BST_BLUE,
        borderRight: '1px solid rgba(0,0,0,0.12)',
        display: 'flex',
        flexDirection: 'column',
        zIndex: 1000,
        boxSizing: 'border-box',
      }}
    >
      <div style={{ padding: '1rem 1.15rem 0.75rem', flexShrink: 0 }}>
        <div
          style={{
            color: 'rgba(255,255,255,0.5)',
            fontSize: 10,
            fontWeight: 600,
            letterSpacing: '1px',
            textTransform: 'uppercase',
            marginBottom: 8,
          }}
        >
          Access level (demo)
        </div>
        <div style={{ display: 'flex', backgroundColor: 'rgba(0,0,0,0.2)', borderRadius: 8, padding: 3 }}>
          {TIERS.map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => setTier(t)}
              style={{
                flex: 1,
                textAlign: 'center',
                padding: '6px 2px',
                fontSize: 11,
                fontWeight: t === tier ? 600 : 500,
                color: t === tier ? BST_BLUE : 'rgba(255,255,255,0.7)',
                backgroundColor: t === tier ? '#ffffff' : 'transparent',
                borderRadius: 6,
                cursor: 'pointer',
                transition: 'all 0.15s ease',
                border: '1px solid transparent',
              }}
            >
              {t}
            </button>
          ))}
        </div>
        <p style={{ fontSize: 10.5, color: 'rgba(255,255,255,0.45)', margin: '8px 0 0', lineHeight: 1.4 }}>
          Starter limits filters and drill; Essentials hides AI menu actions; Pro enables B(A)ST(I) and full interactivity.
        </p>
      </div>

      <nav style={{ padding: '0.25rem 0.7rem 0.35rem', display: 'flex', flexDirection: 'column', flex: 1, overflowY: 'auto', minHeight: 0 }}>
        {navItems.map((item, idx) => {
          const prevSection = idx > 0 ? navItems[idx - 1].section : null;
          const showSectionHeader = item.section && item.section !== prevSection;
          return (
            <React.Fragment key={item.path}>
              {showSectionHeader && (
                <div
                  style={{
                    fontSize: 9.5,
                    fontWeight: 700,
                    letterSpacing: '0.08em',
                    textTransform: 'uppercase',
                    color: 'rgba(255,255,255,0.4)',
                    padding: idx === 0 ? '6px 12px 4px' : '14px 12px 4px',
                  }}
                >
                  {item.section}
                </div>
              )}
              <Link to={item.path} style={linkStyle(item.path)}>
                <span style={{ display: 'flex', alignItems: 'center', width: 22, justifyContent: 'center', color: 'inherit' }}>
                  {item.icon}
                </span>
                <span style={{ flex: 1, lineHeight: 1.35, display: 'flex', alignItems: 'center', gap: 6 }}>
                  {item.label}
                </span>
              </Link>
            </React.Fragment>
          );
        })}
        <div style={{ flex: 1, minHeight: 8 }} />
      </nav>

      <div
        style={{
          padding: '0.875rem 1.15rem',
          borderTop: '1px solid rgba(255,255,255,0.15)',
          display: 'flex',
          alignItems: 'center',
          gap: 10,
        }}
      >
        <div
          style={{
            width: 36,
            height: 36,
            backgroundColor: 'rgba(255,255,255,0.2)',
            border: '1px solid rgba(255,255,255,0.3)',
            borderRadius: '50%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            flexShrink: 0,
            color: '#fff',
            fontWeight: 700,
            fontSize: 12,
          }}
        >
          BST
        </div>
        <div style={{ lineHeight: 1.35 }}>
          <div style={{ color: '#ffffff', fontWeight: 600, fontSize: 13 }}>BST Media</div>
          <div style={{ color: 'rgba(255,255,255,0.5)', fontSize: 11.5 }}>{tier} · demo user</div>
        </div>
      </div>
    </aside>
  );
}
